import{_ as p,a0 as r,w as o,s as d,I as s,x as i,a1 as n,A as e,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"初步瞭解 Git | LCTT x X-CMD","titleTemplate":false,"description":"初步瞭解 Git | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"初步瞭解 Git | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"初步瞭解 Git | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160711 Getting started with Git","title":"初步瞭解 Git","tag":"201608","desc":""},"relativePath":"201608/20160711 Getting started with Git.md","filePath":"[post].md"}'),g={name:"201608/20160711 Getting started with Git.md"};function b(u,t,h,G,m,f){const a=r("Link");return o(),d("div",null,[t[25]||(t[25]=s("h1",{id:"初步瞭解-git",tabindex:"-1"},[i("初步瞭解 Git "),s("a",{class:"header-anchor",href:"#初步瞭解-git","aria-label":"Permalink to “初步瞭解 Git”"},"​")],-1)),t[26]||(t[26]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/get_started_lead.jpeg?itok=r22AKc6P",alt:""})],-1)),t[27]||(t[27]=s("p",null,[s("em",null,"圖片來源：opensource.com")],-1)),s("p",null,[t[1]||(t[1]=i("在這個系列的",-1)),n(a,{href:"https://linux.cn/article-7639-1.html"},{default:e(()=>[...t[0]||(t[0]=[i("介紹篇",-1)])]),_:1}),t[2]||(t[2]=i("中，我們學習到了誰應該使用 Git，以及 Git 是用來做什麼的。今天，我們將學習如何克隆公共 Git 倉庫，以及如何提取出獨立的文件而不用克隆整個倉庫。",-1))]),t[28]||(t[28]=l(`<p>由於 Git 如此流行，因而如果你能夠至少熟悉一些基礎的 Git 知識也能為你的生活帶來很多便捷。如果你可以掌握 Git 基礎（你可以的，我發誓！），那麼你將能夠下載任何你需要的東西，甚至還可能做一些貢獻作為回饋。畢竟，那就是開源的精髓所在：你擁有獲取你使用的軟件代碼的權利，擁有和他人分享的自由，以及只要你願意就可以修改它的權利。只要你熟悉了 Git，它就可以讓這一切都變得很容易。</p><p>那麼，讓我們一起來熟悉 Git 吧。</p><h3 id="讀和寫" tabindex="-1">讀和寫 <a class="header-anchor" href="#讀和寫" aria-label="Permalink to “讀和寫”">​</a></h3><p>一般來説，有兩種方法可以和 Git 倉庫交互：你可以從倉庫中讀取，或者你也能夠向倉庫中寫入。它就像一個文件：有時候你打開一個文檔只是為了閲讀它，而其它時候你打開文檔是因為你需要做些改動。</p><p>本文僅講解如何從 Git 倉庫讀取。我們將會在後面的一篇文章中講解如何向 Git 倉庫寫回的主題。</p><h3 id="git-還是-github" tabindex="-1">Git 還是 GitHub？ <a class="header-anchor" href="#git-還是-github" aria-label="Permalink to “Git 還是 GitHub？”">​</a></h3><p>一句話澄清：Git 不同於 GitHub（或 GitLab，或 Bitbucket）。Git 是一個命令列程序，所以它就像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git</span></span>
<span class="line"><span>usage: Git [--version] [--help] [-C &lt;path&gt;] </span></span>
<span class="line"><span>  [-p | --paginate | --no-pager] [--bare]</span></span>
<span class="line"><span>  [--Git-dir=&lt;path&gt;] &lt;command&gt; [&lt;args&gt;]</span></span></code></pre></div><p>由於 Git 是開源的，所以就有許多聰明人圍繞它構建了基礎軟件；這些基礎軟件，包括在他們自己身邊，都已經變得非常流行了。</p><p>我的文章系列將首先教你純粹的 Git 知識，因為一旦你理解了 Git 在做什麼，那麼你就無需關心正在使用的前端工具是什麼了。然而，我的文章系列也將涵蓋通過流行的 Git 服務完成每項任務的常用方法，因為那些將可能是你首先會遇到的。</p><h3 id="安裝-git" tabindex="-1">安裝 Git <a class="header-anchor" href="#安裝-git" aria-label="Permalink to “安裝 Git”">​</a></h3><p>在 Linux 系統上，你可以從所使用的發行版軟件倉庫中獲取並安裝 Git。BSD 用户應當在 Ports 樹的 devel 部分查找 Git。</p>`,12)),s("p",null,[t[4]||(t[4]=i("對於閉源的操作系統，請前往其",-1)),n(a,{href:"https://git-scm.com/download"},{default:e(()=>[...t[3]||(t[3]=[i("項目官網",-1)])]),_:1}),t[5]||(t[5]=i("，並根據説明安裝。一旦安裝後，在 Linux、BSD 和 Mac OS X 上的命令應當沒有任何差別。Windows 用户需要調整 Git 命令，從而和 Windows 文件系統相匹配，或者安裝 Cygwin 以原生的方式運行 Git，而不受 Windows 文件系統轉換問題的羈絆。",-1))]),t[29]||(t[29]=s("h3",{id:"git-下午茶",tabindex:"-1"},[i("Git 下午茶 "),s("a",{class:"header-anchor",href:"#git-下午茶","aria-label":"Permalink to “Git 下午茶”"},"​")],-1)),t[30]||(t[30]=s("p",null,"並非每個人都需要立刻將 Git 加入到我們的日常生活中。有些時候，你和 Git 最多的交互就是訪問一個代碼庫，下載一兩個文件，然後就不用它了。以這樣的方式看待 Git，它更像是下午茶而非一次正式的宴會。你進行一些禮節性的交談，獲得了需要的信息，然後你就會離開，至少接下來的三個月你不再想這樣説話。",-1)),t[31]||(t[31]=s("p",null,"當然，那是可以的。",-1)),t[32]||(t[32]=s("p",null,"一般來説，有兩種方法訪問 Git：使用命令列，或者使用一種神奇的因特網技術通過 web 瀏覽器快速輕鬆地訪問。",-1)),s("p",null,[t[7]||(t[7]=i("假設你想要給終端安裝一個回收站，因為你已經被 rm 命令毀掉太多次了。你可能聽説過 Trashy ，它稱自己為「理智的 rm 命令中間人」，也許你想在安裝它之前閲讀它的文檔。幸運的是，",-1)),n(a,{href:"https://gitlab.com/trashy/trashy"},{default:e(()=>[...t[6]||(t[6]=[i("Trashy 公開地託管在 GitLab.com",-1)])]),_:1}),t[8]||(t[8]=i("。",-1))]),t[33]||(t[33]=s("h3",{id:"landgrab",tabindex:"-1"},[i("Landgrab "),s("a",{class:"header-anchor",href:"#landgrab","aria-label":"Permalink to “Landgrab”"},"​")],-1)),t[34]||(t[34]=s("p",null,"我們工作的第一步是對這個 Git 倉庫使用 landgrab 排序方法：我們會克隆這個完整的倉庫，然後會根據內容排序。由於該倉庫是託管在公共的 Git 服務平台上，所以有兩種方式來完成工作：使用命令列，或者使用 web 界面。",-1)),s("p",null,[t[10]||(t[10]=i("要想使用 Git 獲取整個倉庫，就要使用 git clone 命令和 Git 倉庫的 URL 作為參數。如果你不清楚正確的 URL 是什麼，倉庫應該會告訴你的。GitLab 為你提供了 ",-1)),n(a,{href:"https://gitlab.com/trashy/trashy.git"},{default:e(()=>[...t[9]||(t[9]=[i("Trashy",-1)])]),_:1}),t[11]||(t[11]=i(" 倉庫的用於拷貝粘貼的 URL。",-1))]),t[35]||(t[35]=l(`<p><img src="https://opensource.com/sites/default/files/1_gitlab-url.jpg" alt=""></p><p>你也許注意到了，在某些服務平台上，會同時提供 SSH 和 HTTPS 鏈接。只有當你擁有倉庫的寫權限時，你才可以使用 SSH。否則的話，你必須使用 HTTPS URL。</p><p>一旦你獲得了正確的 URL，克隆倉庫是非常容易的。就是 git clone 該 URL 即可，以及一個可選的指定要克隆到的目錄。默認情況下會將 git 目錄克隆到你當前所在的目錄；例如，&#39;trashy.git&#39; 將會克隆到你當前位置的 &#39;trashy&#39; 目錄。我使用 .clone 擴展名標記那些只讀的倉庫，而使用 .git 擴展名標記那些我可以讀寫的倉庫，不過這並不是官方要求的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://gitlab.com/trashy/trashy.git trashy.clone</span></span>
<span class="line"><span>Cloning into &#39;trashy.clone&#39;...</span></span>
<span class="line"><span>remote: Counting objects: 142, done.</span></span>
<span class="line"><span>remote: Compressing objects: 100% (91/91), done.</span></span>
<span class="line"><span>remote: Total 142 (delta 70), reused 103 (delta 47)</span></span>
<span class="line"><span>Receiving objects: 100% (142/142), 25.99 KiB | 0 bytes/s, done.</span></span>
<span class="line"><span>Resolving deltas: 100% (70/70), done.</span></span>
<span class="line"><span>Checking connectivity... done.</span></span></code></pre></div><p>一旦成功地克隆了倉庫，你就可以像對待你電腦上任何其它目錄那樣瀏覽倉庫中的文件。</p><p>另外一種獲得倉庫拷貝的方式是使用 web 界面。GitLab 和 GitHub 都會提供一個 .zip 格式的倉庫快照文件。GitHub 有一個大大的綠色下載按鈕，但是在 GitLab 中，可以在瀏覽器的右側找到並不顯眼的下載按鈕。</p><p><img src="https://opensource.com/sites/default/files/1_gitlab-zip.jpg" alt=""></p><h3 id="仔細挑選" tabindex="-1">仔細挑選 <a class="header-anchor" href="#仔細挑選" aria-label="Permalink to “仔細挑選”">​</a></h3><p>另外一種從 Git 倉庫中獲取文件的方法是找到你想要的文件，然後把它從倉庫中拽出來。只有 web 界面才提供這種方法，本質上來説，你看到的是別人的倉庫克隆；你可以把它想像成一個 HTTP 共享目錄。</p><p>使用這種方法的問題是，你也許會發現某些文件並不存在於原始倉庫中，因為完整形式的文件可能只有在執行 make 命令後才能構建，那只有你下載了完整的倉庫，閲讀了 README 或者 INSTALL 文件，然後運行相關命令之後才會產生。不過，假如你確信文件存在，而你只想進入倉庫，獲取那個文件，然後離開的話，你就可以那樣做。</p><p>在 GitLab 和 GitHub 中，單擊文件鏈接，並在 Raw 模式下查看，然後使用你的 web 瀏覽器的保存功能，例如：在 Firefox 中，“文件” &gt; “保存頁面為”。在一個 GitWeb 倉庫中（這是一個某些更喜歡自己託管 git 的人使用的私有 git 倉庫 web 查看器），Raw 查看鏈接在文件列表視圖中。</p><p><img src="https://opensource.com/sites/default/files/1_webgit-file.jpg" alt=""></p><h3 id="最佳實踐" tabindex="-1">最佳實踐 <a class="header-anchor" href="#最佳實踐" aria-label="Permalink to “最佳實踐”">​</a></h3><p>通常認為，和 Git 交互的正確方式是克隆完整的 Git 倉庫。這樣認為是有幾個原因的。首先，可以使用 git pull 命令輕鬆地使克隆倉庫保持更新，這樣你就不必在每次文件改變時就重回 web 站點獲得一份全新的拷貝。第二，你碰巧需要做些改進，只要保持倉庫整潔，那麼你可以非常輕鬆地向原來的作者提交所做的變更。</p><p>現在，可能是時候練習查找感興趣的 Git 倉庫，然後將它們克隆到你的硬盤中了。只要你瞭解使用終端的基礎知識，那就不會太難做到。還不知道基本的終端使用方式嗎？那再給多我 5 分鐘時間吧。</p><h3 id="終端使用基礎" tabindex="-1">終端使用基礎 <a class="header-anchor" href="#終端使用基礎" aria-label="Permalink to “終端使用基礎”">​</a></h3><p>首先要知道的是，所有的文件都有一個路徑。這是有道理的；如果我讓你在常規的非終端環境下為我打開一個文件，你就要導航到文件在你硬盤的位置，並且直到你找到那個文件，你要瀏覽一大堆窗口。例如，你也許要點擊你的家目錄 &gt; 圖片 &gt; InktoberSketches &gt; monkey.kra。</p><p>在那樣的場景下，文件 monkeysketch.kra 的路徑是：$HOME/圖片/InktoberSketches/monkey.kra。</p><p>在終端中，除非你正在處理一些特殊的系統管理員任務，你的文件路徑通常是以 $HOME 開頭的（或者，如果你很懶，就使用 ~ 字符），後面緊跟着一些列的文件夾直到文件名自身。</p><p>這就和你在 GUI 中點擊各種圖標直到找到相關的文件或文件夾類似。</p><p>如果你想把 Git 倉庫克隆到你的文檔目錄，那麼你可以打開一個終端然後運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://gitlab.com/foo/bar.git </span></span>
<span class="line"><span>$HOME/文檔/bar.clone</span></span></code></pre></div><p>一旦克隆完成，你可以打開一個文件管理器窗口，導航到你的文檔文件夾，然後你就會發現 bar.clone 目錄正在等待着你訪問。</p><p>如果你想要更高級點，你或許會在以後再次訪問那個倉庫，可以嘗試使用 git pull 命令來查看項目有沒有更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd $HOME/文檔/bar.clone</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>bar.clone</span></span>
<span class="line"><span>$ git pull</span></span></code></pre></div><p>到目前為止，你需要初步瞭解的所有終端命令就是那些了，那就去探索吧。你實踐得越多，Git 掌握得就越好（熟能生巧），這是重點，也是事情的本質。</p><hr>`,27)),s("p",null,[t[13]||(t[13]=i("via: ",-1)),n(a,{href:"https://opensource.com/life/16/7/stumbling-git"},{default:e(()=>[...t[12]||(t[12]=[i("https://opensource.com/life/16/7/stumbling-git",-1)])]),_:1})]),s("p",null,[t[17]||(t[17]=i("作者：",-1)),n(a,{href:"https://opensource.com/users/seth"},{default:e(()=>[...t[14]||(t[14]=[i("Seth Kenlon",-1)])]),_:1}),t[18]||(t[18]=i(" 譯者：",-1)),n(a,{href:"https://github.com/chrisleegit"},{default:e(()=>[...t[15]||(t[15]=[i("ChrisLeeGit",-1)])]),_:1}),t[19]||(t[19]=i(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[16]||(t[16]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[22]||(t[22]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[20]||(t[20]=[i("LCTT",-1)])]),_:1}),t[23]||(t[23]=i(" 原創翻譯，",-1)),n(a,{href:"https://linux.cn/"},{default:e(()=>[...t[21]||(t[21]=[i("Linux中國",-1)])]),_:1}),t[24]||(t[24]=i(" 榮譽推出",-1))])])}const C=p(g,[["render",b]]);export{y as __pageData,C as default};
